'use strict';
/* Replace the v1.52.0(v1.52.1) __mxMenuCheck fixture in BOTH test pages, preserving
 * everything else — preview.html / harness.html are not regenerated by the sync. */
const fs = require('fs');
const path = require('path');
const ROOT = path.join(__dirname, '..');
const snippet = fs.readFileSync(path.join(__dirname, 'mx-menu-check.snippet.js'), 'utf8').trimEnd();

const START = '  /* ---- menu pass check (v1.52';
const END   = '\n  window.__mxLb = {';
let ok = 0;
['test/preview.html', 'test/harness.html'].forEach(function (rel) {
  const file = path.join(ROOT, rel);
  let src = fs.readFileSync(file, 'utf8');
  const i = src.indexOf(START);
  if (i === -1) throw new Error(rel + ': start marker not found');
  const j = src.indexOf(END, i);
  if (j === -1) throw new Error(rel + ': end marker not found');
  // keep everything up to i, then the snippet, two newlines, then everything from END onward
  src = src.slice(0, i) + snippet + '\n\n' + src.slice(j + 1); // keep the leading '\n' of END
  // the snippet already starts at col 2; END is '\n  window.__mxLb...' so slice(j+1) keeps '  window.__mxLb...'
  fs.writeFileSync(file, src);
  console.log('replaced in ' + rel + ' (' + snippet.split('\n').length + ' lines)');
  ok++;
});
console.log('done in ' + ok + ' file(s)');
